// Read-only data tables from design/views/ (contract §6): typed cells, bars, heat, groups, sticky
// column, sorting. Views are generated by the project's extractors, so there are no edit controls.
import { html, cx } from '../lib.js';
import { useEffect, useMemo, useState } from '../../vendor/hooks.module.js';
import { Icon } from '../icons.js';
import { formatCell, toNumber, isNumericCol } from '../format.js';
import { useStore } from '../store.js';
import { repoStore, blobUrl, fileExists, dpath, reviewOf } from '../repo.js';
import { href } from '../router.js';
import { StatusDot } from './status.js';

/** Blob URL for a private repo image (null while loading / missing). */
export function useBlobUrl(path) {
  const [src, setSrc] = useState(null);
  useEffect(() => {
    let alive = true;
    setSrc(null);
    if (path) blobUrl(path).then((u) => { if (alive) setSrc(u); }).catch(() => {});
    return () => { alive = false; };
  }, [path]);
  return src;
}

function Thumb({ path, alt, size = 28 }) {
  const src = useBlobUrl(path);
  return html`<span class="pg-thumb" style=${{ width: size + 'px', height: size + 'px' }}>
    ${src ? html`<img src=${src} alt=${alt || ''} class="px-up" />` : html`<${Icon} name="image" size=${14} class="muted" />`}
  </span>`;
}

function AssetCell({ id }) {
  const a = useStore(repoStore, (s) => s.assets.find((x) => x.id === id) || null);
  useStore(repoStore, (s) => s.reviews);
  if (!a) return html`<span class="muted mono" title="Unknown asset">${id}</span>`;
  const isImg = /\.(png|jpe?g|gif|webp)$/i.test(a.path || '');
  return html`<a class="cell-asset" href=${href.asset(a.id, a.group)} title=${a.name || a.id}>
    ${isImg ? html`<${Thumb} path=${a.path} alt=${a.name} />` : html`<span class="tag">${a.name || a.id}</span>`}
    <${StatusDot} status=${reviewOf(a).status} />
  </a>`;
}

function imagePath(v) {
  const s = String(v || '').replace(/^\/+/, '');
  if (fileExists(s)) return s;
  const d = dpath(s);
  return fileExists(d) ? d : null;
}

function heatColor(t) {
  const p = Math.round(Math.max(0, Math.min(1, t)) * 100);
  return `color-mix(in oklab, var(--heat-hi) ${p}%, var(--heat-lo))`;
}

function colStats(rows, col) {
  let min = Infinity, max = -Infinity;
  for (const r of rows) {
    const n = toNumber(r[col.key]);
    if (n == null) continue;
    if (n < min) min = n;
    if (n > max) max = n;
  }
  return isFinite(min) ? { min, max, absMax: Math.max(Math.abs(min), Math.abs(max)) } : null;
}

// Long view descriptions collapse to a couple of lines with a "More" toggle.
function Desc({ text }) {
  const [open, setOpen] = useState(false);
  const long = String(text).length > 220;
  return html`<div><p class=${cx('dtable-desc', long && !open && 'is-clamped')}>${text}</p>
    ${long && html`<button type="button" class="link-btn dtable-more" aria-expanded=${String(open)} onClick=${() => setOpen(!open)}>${open ? 'Show less' : 'Show more'}</button>`}</div>`;
}

const widthStyle = (c) => (c.width ? { width: typeof c.width === 'number' ? c.width + 'px' : c.width, minWidth: typeof c.width === 'number' ? c.width + 'px' : c.width } : null);

/** A read-only view table. `view` = the design/views/<id>.json object. */
export function DataTable({ view, maxHeight, showHeader = true }) {
  const cols = Array.isArray(view.columns) ? view.columns : [];
  const rows = Array.isArray(view.rows) ? view.rows : [];
  const [sort, setSort] = useState(null); // {key, dir}
  const stats = useMemo(() => {
    const m = {};
    for (const c of cols) if ((c.bar || c.heat) && isNumericCol(c)) m[c.key] = colStats(rows, c);
    return m;
  }, [view]);
  const sorted = useMemo(() => {
    if (!sort) return rows;
    const col = cols.find((c) => c.key === sort.key);
    const num = isNumericCol(col);
    const arr = rows.slice();
    arr.sort((a, b) => {
      const va = a[sort.key], vb = b[sort.key];
      let d;
      if (num) d = (toNumber(va) ?? -Infinity) - (toNumber(vb) ?? -Infinity);
      else d = String(va ?? '').localeCompare(String(vb ?? ''), undefined, { numeric: true });
      return sort.dir === 'asc' ? d : -d;
    });
    return arr;
  }, [view, sort]);
  const grouped = !sort && rows.some((r) => r._group);
  const items = [];
  let lastGroup = null;
  sorted.forEach((r, ri) => {
    if (grouped && r._group && r._group !== lastGroup) { items.push({ group: r._group, key: 'g:' + r._group + ':' + ri }); lastGroup = r._group; }
    items.push({ row: r, key: r._key != null ? String(r._key) : 'r' + ri });
  });
  const toggleSort = (c) => {
    const first = isNumericCol(c) ? 'desc' : 'asc';
    setSort((s) => (!s || s.key !== c.key ? { key: c.key, dir: first } : s.dir === first ? { key: c.key, dir: first === 'asc' ? 'desc' : 'asc' } : null));
  };
  const title = view.title || view.id;

  return html`<div class="dtable-wrap pg-view">
    ${showHeader && html`<div class="dtable-head">
      <div class="dtable-title-row">
        <h4 class="dtable-title">${title}</h4>
        <span class="badge badge-neutral pg-ro-badge" title="Generated from the game's data by a project script. Read-only here."><${Icon} name="lock" size=${10} /> Read-only</span>
      </div>
      ${view.description && html`<${Desc} text=${view.description} />`}
    </div>`}
    <div class="dtable-scroll" style=${maxHeight ? { maxHeight: maxHeight + 'px' } : null}>
      <table class="dtable" aria-label=${title}>
        <thead><tr>
          ${cols.map((c) => {
            const num = isNumericCol(c);
            const s = sort && sort.key === c.key ? sort.dir : null;
            return html`<th key=${c.key} scope="col" class=${cx(num && 'num', c.sticky && 'sticky-col', c.align && 'align-' + c.align)} style=${widthStyle(c)}
              aria-sort=${s ? (s === 'asc' ? 'ascending' : 'descending') : undefined} title=${c.hint || undefined}>
              <button type="button" class="th-btn" onClick=${() => toggleSort(c)} aria-label=${`${c.label || c.key}${c.hint ? ` — ${c.hint}` : ''}. Sort`}>
                <span>${c.label != null ? c.label : c.key}</span>
                ${c.hint && html`<${Icon} name="info" size=${11} class="th-hint" />`}
                <span class=${cx('sort-ind', s && 'on')}><${Icon} name=${s === 'asc' ? 'chevron-up' : 'chevron-down'} size=${11} /></span>
              </button>
            </th>`;
          })}
        </tr></thead>
        <tbody>
          ${items.map((it) => {
            if (it.group) return html`<tr class="dt-group" key=${it.key}><th colspan=${cols.length} scope="colgroup">${it.group}</th></tr>`;
            const r = it.row;
            return html`<tr key=${it.key} class=${cx(r._highlight && 'is-hl')} title=${r._note || undefined}>
              ${cols.map((c) => {
                const v = r[c.key];
                const t = c.type || 'text';
                const num = isNumericCol(c);
                const n = num ? toNumber(v) : null;
                const st = stats[c.key];
                let content;
                if (t === 'asset') content = v ? html`<${AssetCell} id=${String(v)} />` : '';
                else if (t === 'image') { const p = v ? imagePath(v) : null; content = p ? html`<span class="cell-img"><${Thumb} path=${p} /></span>` : (v ? html`<span class="muted mono">${String(v)}</span>` : ''); }
                else if (t === 'tag') content = v != null && v !== '' ? html`<span class="tag">${String(v)}</span>` : '';
                else if (t === 'bool') content = v == null || v === '' ? '' : html`<span class=${cx('bool', formatCell(c, v) === 'Yes' && 'on')}><${Icon} name=${formatCell(c, v) === 'Yes' ? 'check' : 'minus'} size=${12} /> ${formatCell(c, v)}</span>`;
                else if (t === 'color' && /^#[0-9a-f]{3,8}$/i.test(String(v || ''))) content = html`<span class="pg-color"><span class="swatch" style=${{ background: String(v) }}></span><span class="mono">${String(v)}</span></span>`;
                else content = formatCell(c, v);
                const style = {};
                if (c.heat && st && n != null) style.background = heatColor(st.max === st.min ? 0.5 : (n - st.min) / (st.max - st.min));
                return html`<td key=${c.key} class=${cx(num && 'num', c.sticky && 'sticky-col', c.align && 'align-' + c.align, t === 'text' && String(v ?? '').length > 60 && 'wrap')} style=${style}>
                  ${c.bar && st && n != null && st.absMax > 0 && html`<span class="cell-bar" style=${{ width: (Math.abs(n) / st.absMax) * 100 + '%' }} aria-hidden="true"></span>`}
                  <span class="cell-v">${content}</span>
                </td>`;
              })}
            </tr>`;
          })}
          ${!rows.length && html`<tr><td colspan=${cols.length || 1} class="dt-empty">This table has no rows yet. The project's extractor script fills it in.</td></tr>`}
        </tbody>
      </table>
    </div>
    <div class="dtable-foot muted">
      <span>${rows.length} row${rows.length === 1 ? '' : 's'}</span>
      ${view.source && html`<span class="pg-source" title="Where these numbers come from">${view.source}</span>`}
    </div>
  </div>`;
}

export function UnknownChip({ kind, id }) {
  return html`<span class="directive-warn"><${Icon} name="alert" size=${12} /> Unknown ${kind} <code>${id}</code></span>`;
}

function useView(id) { return useStore(repoStore, (s) => s.views[id] || null); }

// {{view:ID}} / {{table:ID}} island
export function ViewDirective({ id }) {
  const view = useView(id);
  if (!view) return html`<${UnknownChip} kind="data table" id=${id} />`;
  if (view.error) return html`<span class="directive-warn"><${Icon} name="alert" size=${12} /> <code>views/${id}.json</code> can't be read: ${view.error}</span>`;
  return html`<${DataTable} view=${view} />`;
}

// {{stats:ID}} island — rows as stat cards
export function StatsDirective({ id }) {
  const view = useView(id);
  if (!view) return html`<${UnknownChip} kind="data table" id=${id} />`;
  const cols = view.columns || [];
  const byKey = (k) => cols.find((c) => c.key === k);
  const labelCol = byKey('label') || cols[0];
  const valueCol = byKey('value') || cols[1] || cols[0];
  const hintCol = byKey('hint');
  return html`<div class="stat-grid" role="list" aria-label=${view.title || id}>
    ${(view.rows || []).map((r, i) => html`<div class=${cx('stat-card', r._highlight && 'is-hl')} role="listitem" key=${r._key || i} title=${r._note || undefined}>
      <div class="stat-label">${labelCol ? formatCell(labelCol, r[labelCol.key]) : r._key}</div>
      <div class="stat-value">${valueCol ? formatCell(valueCol, r[valueCol.key]) : ''}</div>
      ${hintCol && r[hintCol.key] != null && r[hintCol.key] !== '' && html`<div class="stat-hint">${formatCell(hintCol, r[hintCol.key])}</div>`}
    </div>`)}
  </div>`;
}
